options(stringsAsFactors = FALSE)
stopifnot(getRversion() == "4.6.1")
root <- normalizePath(getwd(), mustWork = TRUE)
out <- file.path(root, "audit/manuscript_nature_health/revision_2026_09_11/consolidated_display_repair_order72k")
sel <- file.path(root, "audit/manuscript_nature_health/consolidated_display_repair_2026_09_11/integration_candidate_order72k")
manifest_path <- file.path(out, "stopped_owner_manifest.csv")
seal_path <- file.path(out, "stopped_owner_seal.json")
stopifnot(!file.exists(manifest_path), !file.exists(seal_path))
sha <- function(p) { con <- file(p, "rb"); on.exit(close(con)); unname(unclass(as.character(openssl::sha256(con)))) }
files <- sort(c(list.files(out, recursive = TRUE, full.names = TRUE, all.files = TRUE), list.files(sel, recursive = TRUE, full.names = TRUE, all.files = TRUE)))
files <- files[!file.info(files)$isdir]
stopifnot(all(Sys.readlink(files) == ""), !anyDuplicated(files))
manifest <- data.frame(path = substring(files, nchar(root) + 2L), sha256 = vapply(files, sha, character(1)), bytes = file.info(files)$size, role = ifelse(grepl("/\\.quarto/", files), "generated candidate cache snapshot", "candidate source output or evidence"))
write.csv(manifest, manifest_path, row.names = FALSE)
main <- file.path(out, "project/render_html_attempt1/ZaunerEtAl2026_NatHealth_phase3_brown.html")
selection <- file.path(sel, "project/render_attempt1/selection.html")
seal <- list(status = "STOPPED_ENVIRONMENT", gate = "REPORT018-ORDER72K-NON-S5-INTEGRATED-PREVIEW-REVIEW", canonical_promotion = FALSE, brown_S5_held = TRUE, manifest = list(path = manifest_path, sha256 = sha(manifest_path), members = nrow(manifest)), return_note = list(path = file.path(out, "stopped_return.md"), sha256 = sha(file.path(out, "stopped_return.md"))), main_html = list(path = main, sha256 = sha(main)), selection_html = list(path = selection, sha256 = sha(selection)), candidate_docx = "Not produced", trial_ledger_sha256 = sha(file.path(out, "trial_ledger.csv")), teardown_sha256 = sha(file.path(out, "teardown_receipt.json")), lease_released = "ORDER72K-VISUAL-LEASE-001", exclusion = "Manifest and this seal excluded from manifest; seal has no self hash", sealed_at_utc = format(Sys.time(), "%Y-%m-%dT%H:%M:%SZ", tz = "UTC"))
jsonlite::write_json(seal, seal_path, auto_unbox = TRUE, pretty = TRUE)
cat(jsonlite::toJSON(seal, auto_unbox = TRUE, pretty = TRUE), "\n")
